def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(s):
        if not s or any(c < "0" or c > "9" for c in s):
            return None
        value = 0
        for i in range(0, len(s), 9):
            chunk = s[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        if any(part == "" for part in parts):
            rejected.append(index)
            continue

        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            entry = history.pop()
            action = entry[0]

            if action == "open":
                del balances[entry[1]]
                frozen.discard(entry[1])
            elif action == "deposit":
                balances[entry[1]] -= entry[2]
            elif action == "withdraw":
                balances[entry[1]] += entry[2]
            elif action == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif action == "freeze":
                frozen.remove(entry[1])
            else:  # unfreeze
                frozen.add(entry[1])

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])

            if amount is None:
                rejected.append(index)
            elif verb == "open":
                if account in balances:
                    rejected.append(index)
                else:
                    balances[account] = amount
                    history.append((verb, account))
            elif verb == "deposit":
                if amount == 0 or account not in balances:
                    rejected.append(index)
                else:
                    balances[account] += amount
                    history.append((verb, account, amount))
            else:
                if (
                    amount == 0
                    or account not in balances
                    or account in frozen
                    or balances[account] < amount
                ):
                    rejected.append(index)
                else:
                    balances[account] -= amount
                    history.append((verb, account, amount))

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])

            if (
                amount is None
                or amount == 0
                or source == destination
                or source not in balances
                or destination not in balances
                or source in frozen
                or balances[source] < amount
            ):
                rejected.append(index)
            else:
                balances[source] -= amount
                balances[destination] += amount
                history.append((verb, source, destination, amount))

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account not in balances:
                rejected.append(index)
            elif verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                else:
                    frozen.add(account)
                    history.append((verb, account))
            else:
                if account not in frozen:
                    rejected.append(index)
                else:
                    frozen.remove(account)
                    history.append((verb, account))

        else:
            rejected.append(index)

    return balances, rejected
